/**
 * The static live demo's "API": answers the web app's reads from bundled sample data
 * (generated by `make demo-fixtures` from a throwaway DEMO_MODE API) and never makes a request.
 * Writes are refused with a DemoBlocked error, which opens the "nothing is saved or sent" dialog.
 * Two flows stay walkable: the new case wizard (in memory only) and judging a sample reply.
 */
import { DEMO_WRITE_EVENT } from "@/lib/demo-mode";
import type { CaseDetail, CaseSummary, Country, Evidence, ReplyOut } from "@/lib/types";
import cases from "./cases.json";
import checklists from "./checklists.json";
import countries from "./countries.json";
import list from "./list.json";
import reply from "./reply.json";
import reviews from "./reviews.json";
import settings from "./settings.json";
import timelines from "./timelines.json";

export class DemoBlocked extends Error {}

export const SAMPLE_REPLY = reply.text;
/** Read synchronously by pages that must never wait in the demo (the landing page). */
export const DEMO_COUNTRIES = countries as Country[];

const byId = <T,>(record: Record<string, unknown>, id: string): T | undefined =>
  Object.prototype.hasOwnProperty.call(record, id) ? (record[id] as T) : undefined;

let draft: CaseDetail | null = null; // the wizard's case: in this tab's memory only

function notFound(): never {
  throw Object.assign(new Error("not in the demo"), { status: 404 });
}

function listCases(query: URLSearchParams): CaseSummary[] {
  const q = (query.get("q") ?? "").toLowerCase();
  const country = query.get("country") ?? "";
  const status = query.get("status") ?? "";
  return (list as CaseSummary[]).filter(
    (c) =>
      (!country || c.country === country) &&
      (!status || c.status === status) &&
      (!q || `${c.title} ${c.company ?? ""}`.toLowerCase().includes(q)),
  );
}

function read(path: string, query: URLSearchParams): unknown {
  let m: RegExpMatchArray | null;
  if (path === "/health") return { ok: true };
  if (path === "/auth/status") return { enabled: false, unlocked: true };
  if (path === "/countries") return countries;
  if (path === "/settings") return settings;
  if (path === "/cases") return listCases(query);
  if (path === "/checklist") {
    const cc = (query.get("country") ?? "").toUpperCase();
    return byId(checklists, cc) ?? checklists._generic;
  }
  if ((m = path.match(/^\/cases\/([^/]+)$/))) {
    if (draft && m[1] === draft.id) return draft;
    return byId(cases, m[1]) ?? notFound();
  }
  if ((m = path.match(/^\/cases\/([^/]+)\/timeline$/))) return byId(timelines, m[1]) ?? [];
  if ((m = path.match(/^\/messages\/([^/]+)\/review$/))) return byId(reviews, m[1]) ?? notFound();
  return notFound();
}

/** The wizard and the reply page can be walked through; nothing leaves this tab. */
function walk(method: string, path: string, body: unknown): unknown {
  let m: RegExpMatchArray | null;
  if (method === "POST" && path === "/cases") {
    const b = body as { description: string; country?: string; company?: string };
    draft = {
      ...(byId<CaseDetail>(cases, (list as CaseSummary[])[0].id) as CaseDetail),
      id: "demo-new-case",
      title: b.company ? `${b.company} — your complaint` : "Your complaint",
      description: b.description,
      company: b.company ?? null,
      country: b.country ?? null,
      region: null,
      status: "intake",
      waiting_for: null,
      pending: null,
      pending_draft: null,
      evidence: [],
      facts: [],
      messages: [],
      deadlines: [],
    } as CaseDetail;
    return draft;
  }
  if (method === "POST" && (m = path.match(/^\/cases\/([^/]+)\/evidence$/)) && draft && m[1] === draft.id) {
    const file = (body as FormData).get("file") as File; // only its name: the file is never read
    const ev: Evidence = {
      id: draft.evidence.length + 1,
      kind: "image",
      filename: file.name,
      sha256: "",
      needs_review: false,
      ocr_confidence: null,
      uploaded_at: new Date().toISOString(),
    };
    draft = { ...draft, evidence: [...draft.evidence, ev] };
    return ev;
  }
  if (method === "POST" && (m = path.match(/^\/cases\/([^/]+)\/replies$/)) && m[1] === reply.case_id) {
    return reply.result as ReplyOut;
  }
  return undefined;
}

export async function demoRequest<T>(method: string, pathAndQuery: string, body?: unknown): Promise<T> {
  const url = new URL(pathAndQuery, "http://demo.invalid");
  if (method === "GET") return read(url.pathname, url.searchParams) as T;
  const walked = walk(method, url.pathname, body);
  if (walked !== undefined) return walked as T;
  if (typeof window !== "undefined") window.dispatchEvent(new Event(DEMO_WRITE_EVENT));
  throw new DemoBlocked(`${method} ${url.pathname}`);
}
